from pathlib import Path
import ast

p=Path('/app/e2e_runner.py')
s=p.read_text(encoding='utf-8')

# Resolve the actual canonical helper parameter name instead of assuming it.
tree=ast.parse(s)
fn=next((n for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name=='_schema_compat'),None)
if fn is None or not fn.args.args:
    raise SystemExit('P120_COMPAT_PATCH_SCHEMA_HELPER_NOT_FOUND')
source_arg=fn.args.args[0].arg
if not source_arg.isidentifier():
    raise SystemExit('P120_COMPAT_PATCH_INVALID_SCHEMA_ARG')

schema_needle='''    if prefix:\n        variants = [_schema_compat(x) for x in prefix]\n        if len(variants) == 1:\n            out["items"] = variants[0]\n        else:\n            out["items"] = {"anyOf": variants}\n    return out\n'''
schema_replacement=f'''    if prefix:\n        variants = [_schema_compat(x) for x in prefix]\n        if len(variants) == 1:\n            out["items"] = variants[0]\n        else:\n            out["items"] = {{"anyOf": variants}}\n\n    # Staging transport compatibility only: OpenAI strict Structured Outputs\n    # requires explicit JSON types for enum/const leaves. Canonical P-120\n    # schemas remain unchanged; deterministic validators still enforce all\n    # removed assertion keywords and authority rules downstream.\n    if "type" not in out:\n        if "const" in out:\n            value = out["const"]\n            if value is None: out["type"] = "null"\n            elif isinstance(value, bool): out["type"] = "boolean"\n            elif isinstance(value, int): out["type"] = "integer"\n            elif isinstance(value, float): out["type"] = "number"\n            elif isinstance(value, str): out["type"] = "string"\n        elif "enum" in out and out["enum"]:\n            vals = out["enum"]\n            if all(isinstance(v, str) for v in vals): out["type"] = "string"\n            elif all(isinstance(v, bool) for v in vals): out["type"] = "boolean"\n            elif all(isinstance(v, int) and not isinstance(v, bool) for v in vals): out["type"] = "integer"\n            elif all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in vals): out["type"] = "number"\n\n    # Packaged v0.5-v0.7 runtime contains exactly two canonical regex\n    # identifier constraints. OpenAI strict Structured Outputs does not accept\n    # pattern; compile both to finite staging-only vocabularies. The untouched\n    # canonical schemas re-validate the returned identifiers downstream.\n    pattern = {source_arg}.get("pattern")\n    if pattern == r"^SYN-[A-Za-z0-9._-]+$":\n        out["type"] = "string"\n        out["enum"] = [f"SYN-{{i:03d}}" for i in range(1, 65)]\n    elif pattern == r"^SNT-[A-Za-z0-9._-]+$":\n        out["type"] = "string"\n        out["enum"] = [f"SNT-{{i:03d}}" for i in range(1, 257)]\n\n    return out\n'''
if schema_needle not in s:
    raise SystemExit('P120_COMPAT_PATCH_TARGET_NOT_FOUND')
patched=s.replace(schema_needle,schema_replacement)

transport_needle='''class BridgeTransport:\n    def __call__(self, body):\n        request_body = copy.deepcopy(body)\n        request_body.setdefault("metadata", {})["p120_e2e_run"] = E2E_RUN\n        fmt = request_body.get("text", {}).get("format", {})\n        if isinstance(fmt.get("schema"), dict):\n            fmt["schema"] = _schema_compat(fmt["schema"])\n        status, payload = bridge({"action": "openai", "request": request_body}, timeout=240)\n        return status, payload\n'''
transport_replacement='''def _find_claim_enum(node):\n    if isinstance(node, dict):\n        vals = node.get("enum")\n        if isinstance(vals, list) and vals and all(isinstance(v, str) and v.startswith("CLM-") for v in vals):\n            return list(vals)\n        for value in node.values():\n            found = _find_claim_enum(value)\n            if found:\n                return found\n    elif isinstance(node, list):\n        for value in node:\n            found = _find_claim_enum(value)\n            if found:\n                return found\n    return None\n\n\ndef _publication_block_budget(report_mode):\n    # Single authority: read the packaged canonical v0.6 publication profile.\n    # No duplicated or silently widened staging budget is permitted.\n    from p120_report.definitions import PUBLICATION_PROFILES\n    profile = PUBLICATION_PROFILES.get(report_mode)\n    if not isinstance(profile, dict):\n        raise RuntimeError(f"P120_PUBLICATION_PROFILE_UNKNOWN:{report_mode}")\n    budget = profile.get("max_blocks")\n    if not isinstance(budget, int) or budget < 1:\n        raise RuntimeError(f"P120_PUBLICATION_BLOCK_BUDGET_INVALID:{report_mode}:{budget}")\n    return budget\n\n\ndef _compile_analytical_transport_schema(schema, report_mode):\n    if not isinstance(schema, dict):\n        return schema, None\n    props = schema.get("properties")\n    if not isinstance(props, dict):\n        return schema, None\n    required_keys = {"selected_claim_ids", "omitted_claim_ids", "synthesis_units"}\n    if not required_keys.issubset(props.keys()):\n        return schema, None\n\n    selected_ids = _find_claim_enum(props["selected_claim_ids"])\n    omitted_ids = _find_claim_enum(props["omitted_claim_ids"])\n    if not selected_ids or not omitted_ids or set(selected_ids) != set(omitted_ids):\n        raise RuntimeError("P120_ANALYTICAL_PARTITION_ENUM_MISMATCH")\n    if len(selected_ids) != len(set(selected_ids)):\n        raise RuntimeError("P120_ANALYTICAL_PARTITION_DUPLICATE_CLAIM_ID")\n\n    synth_schema = props.get("synthesis_units")\n    if not isinstance(synth_schema, dict) or not isinstance(synth_schema.get("items"), dict):\n        raise RuntimeError("P120_ANALYTICAL_SYNTHESIS_SCHEMA_MISSING")\n    unit_schema = copy.deepcopy(synth_schema["items"])\n    budget = _publication_block_budget(report_mode)\n    slot_names = [f"slot_{i:02d}" for i in range(1, budget + 1)]\n\n    # Lossless staging transport encoding #1: every eligible claim receives\n    # exactly one explicit model disposition. This does not authorize, add,\n    # drop or repair claims; canonical validation remains authoritative.\n    out = copy.deepcopy(schema)\n    out_props = out["properties"]\n    out_props.pop("selected_claim_ids", None)\n    out_props.pop("omitted_claim_ids", None)\n    out_props["claim_dispositions"] = {\n        "type": "object",\n        "properties": {\n            cid: {"type": "string", "enum": ["selected", "omitted"]}\n            for cid in selected_ids\n        },\n        "required": list(selected_ids),\n        "additionalProperties": False,\n    }\n\n    # Lossless staging transport encoding #2: compile the downstream v0.6\n    # publication block budget into a fixed nullable-slot object. OpenAI can\n    # never emit more synthesis units than the canonical report mode allows.\n    # The slots are decoded back to the original synthesis_units array before\n    # the untouched v0.5 validator and v0.6 composer see the result.\n    out_props.pop("synthesis_units", None)\n    out_props["synthesis_slots"] = {\n        "type": "object",\n        "properties": {\n            name: {"anyOf": [copy.deepcopy(unit_schema), {"type": "null"}]}\n            for name in slot_names\n        },\n        "required": slot_names,\n        "additionalProperties": False,\n    }\n\n    req = [x for x in out.get("required", []) if x not in ("selected_claim_ids", "omitted_claim_ids", "synthesis_units")]\n    for x in ("claim_dispositions", "synthesis_slots"):\n        if x not in req:\n            req.append(x)\n    out["required"] = req\n    return out, {\n        "allowed_ids": list(selected_ids),\n        "slot_names": slot_names,\n        "budget": budget,\n        "report_mode": report_mode,\n    }\n\n\ndef _decode_analytical_transport_object(obj, context):\n    if not isinstance(obj, dict):\n        raise RuntimeError("P120_ANALYTICAL_TRANSPORT_OUTPUT_NOT_OBJECT")\n    allowed_ids = context["allowed_ids"]\n    slot_names = context["slot_names"]\n    budget = context["budget"]\n\n    dispositions = obj.get("claim_dispositions")\n    if not isinstance(dispositions, dict):\n        raise RuntimeError("P120_ANALYTICAL_PARTITION_DISPOSITIONS_MISSING")\n    if set(dispositions.keys()) != set(allowed_ids):\n        raise RuntimeError("P120_ANALYTICAL_PARTITION_KEYS_INCOMPLETE")\n    if any(v not in ("selected", "omitted") for v in dispositions.values()):\n        raise RuntimeError("P120_ANALYTICAL_PARTITION_INVALID_DISPOSITION")\n    if "selected_claim_ids" in obj or "omitted_claim_ids" in obj:\n        raise RuntimeError("P120_ANALYTICAL_PARTITION_MIXED_REPRESENTATION")\n\n    slots = obj.get("synthesis_slots")\n    if not isinstance(slots, dict):\n        raise RuntimeError("P120_ANALYTICAL_SYNTHESIS_SLOTS_MISSING")\n    if set(slots.keys()) != set(slot_names):\n        raise RuntimeError("P120_ANALYTICAL_SYNTHESIS_SLOT_KEYS_INCOMPLETE")\n    if "synthesis_units" in obj:\n        raise RuntimeError("P120_ANALYTICAL_SYNTHESIS_MIXED_REPRESENTATION")\n    units = [slots[name] for name in slot_names if slots[name] is not None]\n    if any(not isinstance(unit, dict) for unit in units):\n        raise RuntimeError("P120_ANALYTICAL_SYNTHESIS_SLOT_INVALID")\n    if len(units) > budget:\n        raise RuntimeError("P120_ANALYTICAL_SYNTHESIS_BUDGET_EXCEEDED")\n\n    selected = [cid for cid in allowed_ids if dispositions[cid] == "selected"]\n    omitted = [cid for cid in allowed_ids if dispositions[cid] == "omitted"]\n    selected_set = set(selected)\n    synth_refs = []\n    for unit in units:\n        refs = unit.get("claim_ids")\n        if not isinstance(refs, list):\n            raise RuntimeError("P120_ANALYTICAL_SYNTHESIS_CLAIM_REFS_INVALID")\n        synth_refs.extend(refs)\n    synth_ref_set = set(synth_refs)\n\n    # Crucial downstream-budget invariant: if a selected claim is absent from\n    # synthesis units, v0.6 composer creates an additional module fallback block.\n    # Do not repair that after the model. Reject it here, fail-closed, so the\n    # canonical composer receives a plan whose block count cannot exceed budget.\n    if not synth_ref_set.issubset(selected_set):\n        raise RuntimeError("P120_ANALYTICAL_SYNTHESIS_REFS_UNSELECTED")\n    if synth_ref_set != selected_set:\n        missing = sorted(selected_set - synth_ref_set)\n        raise RuntimeError("P120_ANALYTICAL_SELECTED_CLAIMS_UNCOVERED:" + ",".join(missing))\n\n    decoded = copy.deepcopy(obj)\n    decoded.pop("claim_dispositions", None)\n    decoded.pop("synthesis_slots", None)\n    decoded["selected_claim_ids"] = selected\n    decoded["omitted_claim_ids"] = omitted\n    decoded["synthesis_units"] = units\n    return decoded\n\n\ndef _decode_analytical_transport_payload(payload, context):\n    converted = 0\n\n    def walk(node):\n        nonlocal converted\n        if isinstance(node, dict):\n            if node.get("type") == "output_text" and isinstance(node.get("text"), str):\n                try:\n                    parsed = json.loads(node["text"])\n                except Exception as exc:\n                    raise RuntimeError(f"P120_ANALYTICAL_TRANSPORT_TEXT_NOT_JSON:{type(exc).__name__}")\n                if isinstance(parsed, dict) and ("claim_dispositions" in parsed or "synthesis_slots" in parsed):\n                    decoded = _decode_analytical_transport_object(parsed, context)\n                    node["text"] = json.dumps(decoded, ensure_ascii=False, separators=(",", ":"))\n                    converted += 1\n                    return\n            for value in node.values():\n                walk(value)\n        elif isinstance(node, list):\n            for value in node:\n                walk(value)\n\n    walk(payload)\n    if converted != 1:\n        raise RuntimeError(f"P120_ANALYTICAL_TRANSPORT_DECODE_COUNT:{converted}")\n    return payload\n\n\ndef _augment_analytical_budget_prompt(request_body, context):\n    if context is None:\n        return\n    budget = context["budget"]\n    report_mode = context["report_mode"]\n    guidance = (\n        "\\n\\nSTAGING TRANSPORT CONSTRAINT — PUBLICATION BUDGET. "\n        f"For report_mode={report_mode}, the canonical downstream publication profile permits at most {budget} report blocks. "\n        f"Use at most {budget} non-null synthesis slots. Every claim you mark selected MUST appear in at least one non-null synthesis slot; "\n        "otherwise the deterministic transport gate will reject the response. Consolidate related selected claims into the same synthesis unit "\n        "when semantically justified. Do not invent claims, do not drop required claim dispositions, and do not change claim authority or evidence. "\n        "Unused synthesis slots must be null."\n    )\n    inputs = request_body.get("input")\n    if not isinstance(inputs, list):\n        raise RuntimeError("P120_ANALYTICAL_BUDGET_PROMPT_INPUT_MISSING")\n    developer_messages = [m for m in inputs if isinstance(m, dict) and m.get("role") == "developer"]\n    if len(developer_messages) != 1:\n        raise RuntimeError("P120_ANALYTICAL_BUDGET_PROMPT_DEVELOPER_COUNT")\n    content = developer_messages[0].get("content")\n    if not isinstance(content, list) or not content or not isinstance(content[0], dict) or not isinstance(content[0].get("text"), str):\n        raise RuntimeError("P120_ANALYTICAL_BUDGET_PROMPT_CONTENT_MISSING")\n    content[0]["text"] += guidance\n\n\nclass BridgeTransport:\n    def __call__(self, body):\n        request_body = copy.deepcopy(body)\n        request_body.setdefault("metadata", {})["p120_e2e_run"] = E2E_RUN\n        fmt = request_body.get("text", {}).get("format", {})\n        analytical_context = None\n        if isinstance(fmt.get("schema"), dict):\n            report_mode = request_body.get("metadata", {}).get("report_mode")\n            transport_schema, analytical_context = _compile_analytical_transport_schema(fmt["schema"], report_mode)\n            if analytical_context is not None:\n                _augment_analytical_budget_prompt(request_body, analytical_context)\n            fmt["schema"] = _schema_compat(transport_schema)\n        status, payload = bridge({"action": "openai", "request": request_body}, timeout=240)\n        if analytical_context is not None and status == 200:\n            payload = _decode_analytical_transport_payload(payload, analytical_context)\n        return status, payload\n'''
if transport_needle not in patched:
    raise SystemExit('P120_TRANSPORT_PATCH_TARGET_NOT_FOUND')
patched=patched.replace(transport_needle,transport_replacement)

# Syntax-check the exact patched runtime before writing it into the image.
ast.parse(patched)
p.write_text(patched,encoding='utf-8')
print(f'P120_COMPAT_PATCH PASS parameter={source_arg} explicit types + SYN/SNT enums + analytical partition codec + report-mode synthesis-slot budget codec')
